"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/animated-text/variants/02-blur-highlight";
import Variant1 from "./components/animated-text/variants/03-progressive-blur-highlight";
const variants = { "blur-highlight": Variant0, "progressive-blur-highlight": Variant1 };
export interface ArtemisTextHighlightProps {
  className?: string;
  variant?: "blur-highlight" | "progressive-blur-highlight";
}
export function ArtemisTextHighlight({
  className,
  variant = "blur-highlight",
}: ArtemisTextHighlightProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { useEffect, useRef, useState } from "react";
import { motion, useInView } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
const words = [
    "We",
    "turn",
    "ideas",
    "into",
    "interfaces",
    "where",
    "movement",
    "creates",
    "clarity,",
    "rhythm",
    "builds",
    "trust,",
    "and",
    "every",
    "interaction",
    "carries",
    "meaning.",
] as const;
const phraseOfWord = (index: number) => {
    if (index >= 2 && index <= 4)
        return 0;
    if (index >= 6 && index <= 8)
        return 1;
    if (index >= 15 && index <= 16)
        return 2;
    return -1;
};
export default function AnimatedTextBlurHighlight() {
    const paragraph = useRef<HTMLParagraphElement>(null);
    const inView = useInView(paragraph, { once: true, amount: 0.1 });
    const [highlight, setHighlight] = useState(-1);
    useEffect(() => {
        if (!inView)
            return;
        let interval: ReturnType<typeof setInterval> | undefined;
        const timeout = setTimeout(() => {
            setHighlight(0);
            interval = setInterval(() => setHighlight((current) => (current + 1) % 3), 1800);
        }, 1600);
        return () => {
            clearTimeout(timeout);
            if (interval)
                clearInterval(interval);
        };
    }, [inView]);
    return (<>
      <p ref={paragraph} className="art:text-pretty art:max-w-4xl art:font-medium art:text-3xl art:text-foreground art:leading-[1.18] art:tracking-[-0.04em] art:@min-[640px]/artemis:text-5xl art:@min-[1024px]/artemis:text-6xl">
        {words.map((word, index) => {
            const phrase = phraseOfWord(index);
            const marked = phrase >= 0 && phrase === highlight;
            const markerClass = index === 4 || index === 8 || index === 16
                ? "art:absolute art:inset-y-[0.03em] art:-right-[0.12em] art:-left-[0.12em] art:-z-10 art:bg-orange-200" : "art:absolute art:inset-y-[0.03em] art:-left-[0.12em] art:-z-10 art:bg-orange-200 art:-right-[0.3em]";
            return (<span key={index}>
              <motion.span className={`art:relative art:isolate art:inline-block art:transition-colors art:duration-200${marked ? " art:text-orange-950" : ""}`} initial={{ transform: "translateY(30%)", opacity: 0, filter: "blur(10px)" }} animate={inView ? { transform: "translateY(0%)", opacity: 1, filter: "blur(0px)" } : { transform: "translateY(30%)", opacity: 0, filter: "blur(10px)" }} transition={{ duration: 0.55, ease: ARTEMIS_EASE_OUT, delay: index * 0.045 }}>
                {phrase >= 0 && (<motion.span aria-hidden="true" className={markerClass} initial={false} style={{ transform: "scaleX(0.78)", opacity: 0 }} animate={{ transform: `scaleX(${marked ? 1 : 0.78})`, opacity: marked ? 1 : 0 }} transition={ARTEMIS_SPRING_SWAP}/>)}
                {word}
              </motion.span>
              {index < words.length - 1 ? " " : null}
            </span>);
        })}
      </p>
    </>);
}

"use client";
// @zeus-internal
import { useEffect, useRef, useState } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_SWAP } from "../../../lib/ease";
const words = [
    "Great",
    "products",
    "emerge",
    "when",
    "clear",
    "thinking",
    "meets",
    "careful",
    "details,",
    "confident",
    "motion,",
    "and",
    "the",
    "patience",
    "to",
    "refine",
    "what",
    "matters.",
] as const;
function phraseOfWord(index: number) {
    if (index >= 4 && index <= 5)
        return 1;
    if (index >= 7 && index <= 8)
        return 2;
    if (index >= 15 && index <= 17)
        return 3;
    return 0;
}
export default function AnimatedTextProgressiveBlurHighlight() {
    const paragraph = useRef<HTMLParagraphElement>(null);
    const inView = useInView(paragraph, { once: true, amount: 0.1 });
    const reducedMotion = useReducedMotion();
    const [stage, setStage] = useState(0);
    useEffect(() => {
        if (!inView)
            return;
        const timers = [1, 2, 3].map((next) => setTimeout(() => setStage(next), (reducedMotion ? 200 : 1615) + (next - 1) * 900));
        return () => timers.forEach(clearTimeout);
    }, [inView, reducedMotion]);
    return (<>
      <p ref={paragraph} className="art:text-pretty art:max-w-4xl art:font-medium art:text-3xl art:text-foreground art:leading-[1.18] art:tracking-[-0.04em] art:@min-[640px]/artemis:text-5xl art:@min-[1024px]/artemis:text-6xl">
        {words.map((word, index) => {
            const phrase = phraseOfWord(index);
            const marked = phrase > 0 && stage >= phrase;
            const markerClass = index === 5 || index === 8 || index === 17
                ? "art:absolute art:inset-y-[0.03em] art:-right-[0.12em] art:-left-[0.12em] art:-z-10 art:bg-orange-200 art:origin-left" : "art:absolute art:inset-y-[0.03em] art:-left-[0.12em] art:-z-10 art:bg-orange-200 art:-right-[0.3em] art:origin-left";
            return (<span key={index}>
              <motion.span className={`art:relative art:isolate art:inline-block art:transition-colors art:duration-200${marked ? " art:text-orange-950" : ""}`} initial={{ transform: "translateY(30%)", opacity: 0, filter: "blur(10px)" }} animate={inView ? { transform: reducedMotion ? "translateY(30%)" : "translateY(0%)", opacity: 1, filter: reducedMotion ? "blur(10px)" : "blur(0px)" } : { transform: "translateY(30%)", opacity: 0, filter: "blur(10px)" }} transition={{ duration: reducedMotion ? 0.2 : 0.55, ease: ARTEMIS_EASE_OUT, delay: reducedMotion ? 0 : index * 0.045 }}>
                {phrase > 0 && (<motion.span aria-hidden="true" className={markerClass} initial={false} style={{ transform: "scaleX(0.78)", opacity: 0 }} animate={{ transform: `scaleX(${reducedMotion ? 0.78 : marked ? 1 : 0.78})`, opacity: marked ? 1 : 0 }} transition={reducedMotion ? { duration: 0.18, ease: ARTEMIS_EASE_OUT } : ARTEMIS_SPRING_SWAP}/>)}
                {word}
              </motion.span>
              {index < words.length - 1 ? " " : null}
            </span>);
        })}
      </p>
    </>);
}
